def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_threats = 0
    desperate_threats = 0

    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 300:
                rich_threats += 1
            if opp.get('hp', 0) <= 4 or opp.get('no_water_days', 0) >= 1:
                desperate_threats += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0)))
                except Exception:
                    pass

    if not alive_opponents:
        return float(min(budget, 10.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    ample_supply = supply >= 23

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2
    if tight_supply:
        urgency += 2
    elif ample_supply:
        urgency -= 1
    if day >= 8:
        urgency += 1

    if urgency >= 7:
        target = max(92.0, highest_prev + 3.0)
    elif urgency >= 4:
        target = max(68.0, avg_prev * 0.78 + 6.0)
    else:
        if highest_prev >= 110:
            target = 34.0 if hp >= 5 and no_water_days == 0 else 82.0
        elif highest_prev >= 90:
            target = 42.0 if hp >= 5 and no_water_days == 0 else 76.0
        elif highest_prev >= 60:
            target = highest_prev * 0.72 + 4.0
        else:
            target = 38.0 if ample_supply else 46.0

    if rich_threats >= 2 and tight_supply:
        target += 8.0
    if desperate_threats >= 2 and hp <= 4:
        target += 6.0
    if hp >= 7 and no_water_days == 0 and highest_prev >= 100:
        target -= 8.0

    reserve = 0.0
    if day <= 7:
        reserve = 70.0 * max(0, 8 - day) * 0.18
    max_affordable = max(0.0, budget - reserve)
    if urgency >= 6:
        max_affordable = budget

    bid = min(target, max_affordable)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, highest_prev + 5.0, 95.0))
    elif hp <= 4 or no_water_days >= 1:
        bid = min(budget, max(bid, highest_prev * 0.9 + 2.0, 72.0))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))
